407	    /**
408	     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
409	     *
410	     * @param orderId 주문 ID
411	     */
412	    @Transactional
413	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
414	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
415	
416	        try {
417	            // OrderBid 조회
418	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
419	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
420	
421	            // 상태를 COMPLETED로 업데이트
422	            if (orderBid.getStatus() == com.fream.back.domain.order.entity.BidStatus.MATCHED) {
423	                log.debug("OrderBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
424	                orderBid.updateStatus(com.fream.back.domain.order.entity.BidStatus.COMPLETED);
425	            }
426	
427	            // SaleBid 상태 업데이트
428	            SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
429	            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
430	                log.debug("SaleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
431	                saleBid.updateStatus(BidStatus.COMPLETED);
432	            }
433	
434	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
435	
436	        } catch (Exception e) {
437	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
438	            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
439	        }
440	    }
