 83	@Slf4j
 84	@Configuration
 85	@RequiredArgsConstructor
 86	public class UpdateShipmentStatusesJobConfig {
 87	
 88	    private final JobRepository jobRepository;
 89	    private final PlatformTransactionManager transactionManager;
 90	    private final EntityManagerFactory entityManagerFactory;
 91	
 92	    private final OrderShipmentRepository orderShipmentRepository;
