336	     * PlaywrightBrowserManager 빈 정의
337	     */
338	    @Bean
339	    public PlaywrightBrowserManager playwrightBrowserManager() {
340	        log.debug("Playwright 브라우저 매니저 빈 생성");
341	        return new PlaywrightBrowserManager();
